package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import org.json.*;import java.io.*;import java.util.*;
/** Bounded shared decoded artwork; one source cell per item, never a whole atlas in a slot. */
final class MenuArt {
 private BitmapShader menuTexture;private final Paint backdropPaint=new Paint(3);
 private static MenuArt shared;final Map<String,JSONObject> items=new LinkedHashMap<>();final Map<String,Integer> cells=new HashMap<>();final Bitmap[] sheets=new Bitmap[5];Bitmap survivors,maleSurvivors,femaleSurvivors,roles,surfaces;final Paint p=new Paint(3);final Rect source=new Rect();final RectF destination=new RectF();
 static synchronized MenuArt get(Context c){if(shared==null)shared=new MenuArt(c.getApplicationContext());return shared;}
 private MenuArt(Context c){try(InputStream in=c.getAssets().open("progression-data.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONArray list=new JSONObject(out.toString("UTF-8")).getJSONArray("items");for(int i=0;i<list.length();i++){JSONObject item=list.getJSONObject(i);items.put(item.getString("id"),item);}}catch(Exception ignored){}try(InputStream in=c.getAssets().open("menu/index.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONObject index=new JSONObject(out.toString("UTF-8"));Iterator<String> keys=index.keys();while(keys.hasNext()){String key=keys.next();cells.put(key,index.optInt(key));}}catch(Exception ignored){}for(int i=0;i<5;i++)sheets[i]=load(c,"menu/items-"+i+".png",1024);survivors=load(c,"menu/survivors.png",1536);femaleSurvivors=load(c,"menu/female-survivors.png",1536);maleSurvivors=load(c,"menu/male-survivors.png",1536);roles=load(c,"menu/role-cards.png",1536);surfaces=load(c,"menu/surfaces.png",1024);}
 private Bitmap load(Context c,String path,int limit){try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=c.getAssets().open(path)){BitmapFactory.decodeStream(in,null,o);}int sample=1;while(Math.max(o.outWidth,o.outHeight)/sample>limit)sample*=2;o.inJustDecodeBounds=false;o.inSampleSize=sample;o.inPreferredConfig=Bitmap.Config.RGB_565;try(InputStream in=c.getAssets().open(path)){return BitmapFactory.decodeStream(in,null,o);}}catch(Exception e){return null;}}
 void backdrop(Canvas c){c.drawColor(0xff191714);if(surfaces==null)return;if(menuTexture==null){int w=surfaces.getWidth()/2,h=surfaces.getHeight()/2;Bitmap tile=Bitmap.createBitmap(surfaces,w,h,w,h);menuTexture=new BitmapShader(tile,Shader.TileMode.REPEAT,Shader.TileMode.REPEAT);Matrix m=new Matrix();m.setScale(256f/w,256f/h);menuTexture.setLocalMatrix(m);}backdropPaint.setShader(menuTexture);backdropPaint.setAlpha(26);c.drawPaint(backdropPaint);backdropPaint.setShader(null);backdropPaint.setAlpha(255);}
 String name(String id){if(id.startsWith("deed:")){String[] parts=id.split(":");return parts.length>1?parts[1]+" House Deed":"House Deed";}JSONObject item=items.get(id);return item==null?id:item.optString("name",id);}
 int rarity(String id){return Rarity.level(items.get(id));}
 void item(Canvas c,String id,float x,float y,float size){if(id.startsWith("deed:")){p.setColor(0xffd7c190);c.drawRect(x+size*.16f,y+size*.08f,x+size*.84f,y+size*.92f,p);p.setColor(0xff6d5030);p.setStrokeWidth(Math.max(1,size*.025f));for(int i=0;i<3;i++)c.drawLine(x+size*.28f,y+size*(.28f+i*.13f),x+size*.72f,y+size*(.28f+i*.13f),p);p.setColor(0xff81322d);c.drawCircle(x+size*.62f,y+size*.74f,size*.12f,p);return;}JSONObject definition=items.get(id);if(definition!=null&&definition.has("backpackSlots")){p.setColor(0xff352b23);c.drawRoundRect(x+size*.17f,y+size*.2f,x+size*.83f,y+size*.86f,size*.1f,size*.1f,p);p.setColor(0xff8a6b46);c.drawRoundRect(x+size*.22f,y+size*.24f,x+size*.78f,y+size*.81f,size*.07f,size*.07f,p);p.setColor(0xffbb9760);c.drawRect(x+size*.31f,y+size*.27f,x+size*.36f,y+size*.76f,p);c.drawRect(x+size*.64f,y+size*.27f,x+size*.69f,y+size*.76f,p);p.setColor(0xffc3ad7a);c.drawRect(x+size*.43f,y+size*.46f,x+size*.57f,y+size*.54f,p);return;}if(ArmsIconPainter.draw(c,definition,x,y,size))return;Integer cell=cells.get(definition==null?id:definition.optString("icon",id));if(cell==null){JSONObject item=items.get(id);if(item!=null&&item.has("armorSlot"))ArmorIconPainter.draw(c,item,x,y,size);return;}Bitmap b=sheets[cell/16];if(b==null)return;int cw=b.getWidth()/4,ch=b.getHeight()/4,local=cell%16;source.set(local%4*cw+2,local/4*ch+2,(local%4+1)*cw-2,(local/4+1)*ch-2);destination.set(x,y,x+size,y+size);p.setColor(Color.WHITE);c.drawBitmap(b,source,destination,p);}
 void role(Canvas c,int role,RectF bounds){if(roles==null)return;int cw=roles.getWidth()/2;source.set(role*cw,0,(role+1)*cw,roles.getHeight());float width=bounds.height()*source.width()/source.height();destination.set(bounds.centerX()-width/2,bounds.top,bounds.centerX()+width/2,bounds.bottom);p.setColor(Color.WHITE);c.drawBitmap(roles,source,destination,p);}
 void survivor(Canvas c,String appearance,String armour,RectF bounds){JSONObject gear=items.get(armour);if(gear!=null&&gear.has("armorSet"))armour=gear.optString("material").equals("metal")?"mail":gear.optString("material").equals("leather")?"tunic":"gambeson";Bitmap atlas=appearance.startsWith("female-")?femaleSurvivors:maleSurvivors;if(atlas!=null){int col="tunic".equals(armour)?1:"gambeson".equals(armour)?2:"mail".equals(armour)?3:0,row=appearance.endsWith("-2")?1:0,cw=atlas.getWidth()/4;int cut=(int)(atlas.getHeight()*.46f),y0=row==0?0:cut,y1=row==0?cut:atlas.getHeight();source.set(col*cw+(int)(cw*.16f),y0+2,col*cw+(int)(cw*.84f),y1-2);float width=bounds.height()*source.width()/source.height();destination.set(bounds.centerX()-width/2,bounds.top,bounds.centerX()+width/2,bounds.bottom);p.setColor(Color.WHITE);c.drawBitmap(atlas,source,destination,p);return;}if(survivors==null)return;int cell="tunic".equals(armour)?1:"gambeson".equals(armour)?2:"mail".equals(armour)?3:0,cw=survivors.getWidth()/2,ch=survivors.getHeight()/2;source.set(cell%2*cw+(int)(cw*.20f),cell/2*ch+3,cell%2*cw+(int)(cw*.80f),(cell/2+1)*ch-3);p.setColor(Color.WHITE);c.drawBitmap(survivors,source,bounds,p);}
}



